CURLcode smtp_escape_eob(struct connectdata *conn, ssize_t nread) {
  ssize_t i, j;
  size_t crlf_count = 0;
  ssize_t new_size;
  char *scratch = NULL;
  char *src, *dst;

  // Count the number of CRLF sequences to determine the scratch buffer size
  for (i = 0, j = 0; i < nread - 1; i++, j++) {
    if (conn->uploadbuf[i] == '\r' && conn->uploadbuf[i + 1] == '\n') {
      crlf_count++;
      i++; // Skip the next byte
    }
  }

  // Allocate a scratch buffer
  new_size = nread + crlf_count;
  scratch = realloc(conn->upload_eobbuf, (size_t)new_size + 1); // +1 for null-terminator
  if (!scratch) {
    return CURLE_OUT_OF_MEMORY;
  }

  conn->upload_eobbuf = scratch;
  src = conn->uploadbuf;
  dst = scratch;

  // Copy and transform the data
  for (i = 0, j = 0; i < nread - 1; i++, j++) {
    if (src[i] == '\r' && src[i + 1] == '\n') {
      *dst++ = src[i];
      *dst++ = src[i + 1];
      *dst++ = '.';
      i++;
    } else {
      *dst++ = src[i];
    }
  }

  // Handle the remaining byte
  if (j < nread) {
    *dst++ = src[j];
  }

  *dst = '\0'; // Null-terminate the string

  // Update the upload buffer and size
  if (crlf_count > 0) {
    free(conn->uploadbuf);
    conn->uploadbuf = scratch;
    conn->uploadbuf_size = (size_t)new_size;
  }

  return CURLE_OK;
}

CURLcode smtp_escape_eob(struct connectdata *conn, ssize_t nread) {
  char *scratch = NULL;
  char *src, *dst;
  size_t i;
  size_t replacements = 0;

  if (nread <= 0)
    return CURLE_OK;

  scratch = malloc(nread * 2 + 1);
  if (!scratch)
    return CURLE_OUT_OF_MEMORY;

  src = conn->upload.upload_buffer;
  dst = scratch;

  for (i = 0; i < (size_t)nread; i++) {
    *dst++ = *src++;
    if (i + 1 < (size_t)nread && src[-1] == '\r' && *src == '\n') {
      // Escape CRLF by inserting a dot, as per RFC 5321
      *dst++ = '.';
      replacements++;
    }
  }

  if (replacements > 0) {
    // Free the original buffer and replace it with the escaped one
    free(conn->upload.upload_buffer);
    conn->upload.upload_buffer = scratch;
    conn->upload.ulbuf = scratch;
    conn->upload.upload_size = dst - scratch;
  } else {
    free(scratch);
  }

  return CURLE_OK;
}

CURLcode smtp_escape_eob(struct connectdata *conn, ssize_t nread) {
  char *scratch = NULL;
  char *src, *dst;
  size_t i, scratch_size;
  bool trailing_crlf = FALSE;

  scratch_size = nread + 2; /* +2 to accommodate for possible CRLF replacements */
  scratch = malloc(scratch_size);
  if (!scratch) {
    return CURLE_OUT_OF_MEMORY;
  }

  src = conn->upload_buffer;
  dst = scratch;

  for (i = 0; i < nread; i++) {
    if (src[i] == '\r' && i + 1 < nread && src[i + 1] == '\n') {
      *dst++ = '\r';
      *dst++ = '\n';
      *dst++ = '.';
      i++; /* skip the next \n */
      trailing_crlf = TRUE;
    } else {
      *dst++ = src[i];
    }
  }

  if (trailing_crlf) {
    *dst++ = '\r';
    *dst++ = '\n';
  }

  if (scratch != conn->upload_buffer) {
    free(conn->upload_buffer);
    conn->upload_buffer = scratch;
    conn->upload_left = dst - scratch;
  } else {
    conn->upload_left = dst - scratch;
  }

  return CURLE_OK;
}

CURLcode escape_eob(struct connectdata *conn, ssize_t nread) {
  size_t i;
  ssize_t replacements = 0;
  unsigned char *scratch = NULL;
  unsigned char *src, *dst;
  bool trailing_crlf = FALSE;

  if (!conn || nread <= 0) {
    return CURLE_OK;
  }

  src = (unsigned char *)conn->upload->data;

  for (i = 1; i < (size_t)nread; ++i) {
    if (src[i] == '\r' && (i + 1 < (size_t)nread) && src[i + 1] == '\n') {
      replacements++;
    }
  }

  if (replacements == 0) {
    if (nread >= 2 && src[nread - 2] == '\r' && src[nread - 1] == '\n') {
      trailing_crlf = TRUE;
    }
    return CURLE_OK;
  }

  scratch = malloc(nread + (ssize_t)nread); /* Maximum possible expansion */
  if (!scratch) {
    return CURLE_OUT_OF_MEMORY;
  }

  dst = scratch;
  for (i = 0; i < (size_t)nread; ++i) {
    if (i < (size_t)nread - 1 && src[i] == '\r' && src[i + 1] == '\n') {
      *dst++ = '.';
      *dst++ = src[i];
      *dst++ = src[i + 1];
      ++i;
    } else {
      *dst++ = src[i];
    }
  }

  if (trailing_crlf) {
    *dst++ = '.';
  }

  Curl_safefree(conn->upload->data);
  conn->upload->data = scratch;
  conn->upload->size = dst - scratch;
  return CURLE_OK;
}

CURLcode escape_eob_markers(struct connectdata *conn, ssize_t nread) {
    char *scratch = NULL;
    size_t scratch_len = 0;
    size_t i, j;
    CURLcode result = CURLE_OK;
    bool trailing_crlf = FALSE;

    scratch = malloc(nread + 2); /* Extra space for potential trailing CRLF */
    if (!scratch) {
        return CURLE_OUT_OF_MEMORY;
    }

    scratch_len = nread + 2;
    for (i = 0, j = 0; i < nread; ++i) {
        if (i + 1 < nread && conn->upload_buffer[i] == '\r' && conn->upload_buffer[i + 1] == '\n') {
            scratch[j++] = '\r';
            scratch[j++] = '\n';
            scratch[j++] = '.';
            i++; /* Skip the next character (newline) */
        } else {
            scratch[j++] = conn->upload_buffer[i];
        }
    }

    if (j + 2 <= scratch_len) {
        scratch[j++] = '\r';
        scratch[j++] = '\n';
        trailing_crlf = TRUE;
    }

    free(conn->upload_buffer);
    conn->upload_buffer = scratch;
    conn->upload_size = j;
    conn->nread = j;

    if (trailing_crlf) {
        conn->upload_buffer[j - 2] = '\0';
    }

    return result;
}
